{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.michael-ltm/browpilot",
  "title": "Browpilot",
  "description": "让 AI Agent 操控你选定的浏览器 profile：标签页、点击、输入、截图和调试。面板里能看到哪些 profile 在线、哪个 Agent 会话正占用哪个标签页。需要在浏览器里安装 Browpilot 扩展。",
  "version": "0.2.4",
  "repository": {
    "url": "https://github.com/michael-ltm/browpilot-src",
    "source": "github"
  },
  "websiteUrl": "https://github.com/michael-ltm/browpilot",
  "_meta": {
    "io.github.opspanel/plugin": {
      "npm": {
        "tarball": "https://github.com/michael-ltm/browpilot/releases/download/v0.2.4/browpilot-0.2.4.tgz",
        "sha256": "3746b86f571cab669e3cedb2667beef1248595a6e765cef02a299dc847e27a42",
        "bin": "browpilot"
      },
      "i18n": {
        "en": {
          "description": "Lets AI agents drive the browser profiles you choose: tabs, clicks, typing, screenshots and debugging. The panel shows which profiles are online and which agent session holds which tab. Requires the Browpilot browser extension.",
          "connected": "Profiles online",
          "profiles": "Browser profiles",
          "leases": "Tabs in use",
          "agents": "Connected agents",
          "colName": "Name",
          "colStatus": "Status",
          "colTabs": "Tabs in use",
          "colReconnects": "Reconnects",
          "colProfile": "Profile",
          "colTab": "Tab",
          "colSession": "Terminal session",
          "colSince": "Since",
          "colConnected": "Connected"
        }
      },
      "ui": [
        {
          "id": "connected",
          "type": "stat",
          "title": "在线 profile",
          "titleKey": "connected",
          "tool": "browser_overview",
          "path": "/connected",
          "refresh": 15
        },
        {
          "id": "profiles",
          "type": "table",
          "title": "浏览器 profile",
          "titleKey": "profiles",
          "tool": "browser_overview",
          "path": "/profiles",
          "refresh": 15,
          "columns": [
            {
              "key": "label",
              "title": "名称",
              "titleKey": "colName"
            },
            {
              "key": "status",
              "title": "状态",
              "titleKey": "colStatus"
            },
            {
              "key": "tabCount",
              "title": "占用的标签页",
              "titleKey": "colTabs"
            },
            {
              "key": "reconnectCount",
              "title": "重连次数",
              "titleKey": "colReconnects"
            }
          ]
        },
        {
          "id": "leases",
          "type": "table",
          "title": "正在使用的标签页",
          "titleKey": "leases",
          "tool": "browser_overview",
          "path": "/leases",
          "refresh": 15,
          "columns": [
            {
              "key": "label",
              "title": "Profile",
              "titleKey": "colProfile"
            },
            {
              "key": "tabId",
              "title": "标签页",
              "titleKey": "colTab"
            },
            {
              "key": "opspanelSession",
              "title": "终端会话",
              "titleKey": "colSession",
              "format": "session"
            },
            {
              "key": "since",
              "title": "开始于",
              "titleKey": "colSince",
              "format": "time"
            }
          ]
        },
        {
          "id": "agents",
          "type": "table",
          "title": "已连接的 Agent",
          "titleKey": "agents",
          "tool": "browser_overview",
          "path": "/agents",
          "refresh": 15,
          "columns": [
            {
              "key": "opspanelSession",
              "title": "终端会话",
              "titleKey": "colSession",
              "format": "session"
            },
            {
              "key": "tabs",
              "title": "占用的标签页",
              "titleKey": "colTabs"
            },
            {
              "key": "connectedAt",
              "title": "连接于",
              "titleKey": "colConnected",
              "format": "time"
            }
          ]
        }
      ]
    }
  }
}

{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.michael-ltm/containers",
  "title": "容器",
  "description": "查看和管理本机的 Docker / Podman 容器：列表、日志、启动、停止、重启和删除。自动找到已安装的引擎，不需要配置。",
  "version": "0.1.1",
  "repository": {
    "url": "https://github.com/michael-ltm/opspanel-plugins",
    "source": "github",
    "subfolder": "cmd/containers"
  },
  "websiteUrl": "https://github.com/michael-ltm/opspanel-plugins/tree/main/cmd/containers",
  "_meta": {
    "io.github.opspanel/plugin": {
      "artifacts": {
        "darwin/amd64": {
          "url": "https://github.com/michael-ltm/opspanel-plugins/releases/download/containers-v0.1.1/containers-darwin-amd64",
          "sha256": "6c5bafe2358ccf7329a43caed7dbc0b497d91b8df0ecfa235710f72a7224ea35"
        },
        "darwin/arm64": {
          "url": "https://github.com/michael-ltm/opspanel-plugins/releases/download/containers-v0.1.1/containers-darwin-arm64",
          "sha256": "5ca645ea8d8abd6b5c59eb3fe21cc51f326f018b551cd8aad37c5084284934c6"
        },
        "linux/amd64": {
          "url": "https://github.com/michael-ltm/opspanel-plugins/releases/download/containers-v0.1.1/containers-linux-amd64",
          "sha256": "685953a84e23386305a1a6b4356c036ff83f8c8900cd84ce40a26cede4af5e78"
        },
        "linux/arm64": {
          "url": "https://github.com/michael-ltm/opspanel-plugins/releases/download/containers-v0.1.1/containers-linux-arm64",
          "sha256": "867010a3d35217918dd276082b3f9bec5e009c03a06bd2212916545d183d50ec"
        },
        "windows/amd64": {
          "url": "https://github.com/michael-ltm/opspanel-plugins/releases/download/containers-v0.1.1/containers-windows-amd64.exe",
          "sha256": "80e432fef1099c09a5635bdab02508164cd9ce7ec7952c0c564a111aefe36c51"
        },
        "windows/arm64": {
          "url": "https://github.com/michael-ltm/opspanel-plugins/releases/download/containers-v0.1.1/containers-windows-arm64.exe",
          "sha256": "4bb755a4107d5198b4601f3c5878f90447efa687c9a431feb2a562742d4a8da4"
        }
      },
      "i18n": {
        "en": {
          "title": "Containers",
          "description": "See and manage this machine's Docker / Podman containers: list, logs, start, stop, restart and remove. Finds the installed engine on its own; nothing to configure.",
          "running": "Running",
          "containers": "Containers",
          "colName": "Name",
          "colImage": "Image",
          "colState": "State",
          "colStatus": "Status",
          "colPorts": "Ports",
          "actLogs": "Logs",
          "actStart": "Start",
          "actStop": "Stop",
          "actRestart": "Restart",
          "actRemove": "Remove",
          "tool.containers_list.title": "List containers",
          "tool.containers_list.description": "Every container on this machine with its state, image and ports",
          "tool.container_logs.title": "View logs",
          "tool.container_logs.description": "The container's latest output",
          "tool.container_start.title": "Start container",
          "tool.container_start.description": "Start a stopped container",
          "tool.container_stop.title": "Stop container",
          "tool.container_stop.description": "Stop a running container; it can be started again",
          "tool.container_restart.title": "Restart container",
          "tool.container_restart.description": "Stop and start a container again",
          "tool.container_remove.title": "Remove container",
          "tool.container_remove.description": "Delete a container and its writable layer; named volumes are kept"
        }
      },
      "ui": [
        {
          "id": "running",
          "type": "stat",
          "title": "运行中",
          "titleKey": "running",
          "tool": "containers_list",
          "path": "/running",
          "refresh": 15
        },
        {
          "id": "containers",
          "type": "table",
          "title": "容器",
          "titleKey": "containers",
          "tool": "containers_list",
          "path": "/containers",
          "refresh": 15,
          "columns": [
            {
              "key": "name",
              "title": "名称",
              "titleKey": "colName"
            },
            {
              "key": "image",
              "title": "镜像",
              "titleKey": "colImage"
            },
            {
              "key": "state",
              "title": "状态",
              "titleKey": "colState",
              "format": "badge"
            },
            {
              "key": "status",
              "title": "详情",
              "titleKey": "colStatus"
            },
            {
              "key": "ports",
              "title": "端口",
              "titleKey": "colPorts"
            }
          ],
          "rowActions": [
            {
              "id": "logs",
              "title": "日志",
              "titleKey": "actLogs",
              "icon": "logs",
              "tool": "container_logs",
              "arguments": {
                "id": "{id}",
                "tail": 200
              },
              "display": "dialog",
              "resultPath": "/logs"
            },
            {
              "id": "start",
              "title": "启动",
              "titleKey": "actStart",
              "icon": "play",
              "tool": "container_start",
              "arguments": {
                "id": "{id}"
              },
              "unless": {
                "key": "state",
                "in": [
                  "running",
                  "restarting"
                ]
              }
            },
            {
              "id": "stop",
              "title": "停止",
              "titleKey": "actStop",
              "icon": "stop",
              "tool": "container_stop",
              "arguments": {
                "id": "{id}"
              },
              "confirm": true,
              "when": {
                "key": "state",
                "in": [
                  "running",
                  "restarting"
                ]
              }
            },
            {
              "id": "restart",
              "title": "重启",
              "titleKey": "actRestart",
              "icon": "refresh",
              "tool": "container_restart",
              "arguments": {
                "id": "{id}"
              },
              "confirm": true,
              "when": {
                "key": "state",
                "in": [
                  "running",
                  "restarting"
                ]
              }
            },
            {
              "id": "remove",
              "title": "删除",
              "titleKey": "actRemove",
              "icon": "trash",
              "tool": "container_remove",
              "arguments": {
                "id": "{id}"
              }
            }
          ]
        }
      ],
      "tools": {
        "containers_list": {
          "title": "列出容器",
          "description": "查看本机所有容器的状态、镜像和端口"
        },
        "container_logs": {
          "title": "查看日志",
          "description": "读取容器最近的输出"
        },
        "container_start": {
          "title": "启动容器",
          "description": "启动一个已停止的容器"
        },
        "container_stop": {
          "title": "停止容器",
          "description": "停止一个运行中的容器，之后还能再启动"
        },
        "container_restart": {
          "title": "重启容器",
          "description": "先停止再启动容器"
        },
        "container_remove": {
          "title": "删除容器",
          "description": "删除容器及其可写层，命名卷会保留"
        }
      }
    }
  }
}

{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.michael-ltm/github-actions",
  "title": "GitHub Actions",
  "description": "在面板里看 GitHub Actions：最近的运行、失败任务出错位置的日志、Release 列表，也能重跑失败的任务。需要一个 GitHub 令牌。",
  "version": "0.1.1",
  "repository": {
    "url": "https://github.com/michael-ltm/opspanel-plugins",
    "source": "github",
    "subfolder": "cmd/github-actions"
  },
  "websiteUrl": "https://github.com/michael-ltm/opspanel-plugins/tree/main/cmd/github-actions",
  "packages": [
    {
      "registryType": "mcpb",
      "identifier": "https://github.com/michael-ltm/opspanel-plugins/releases/download/github-actions-v0.1.1/github-actions-linux-amd64",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "name": "GITHUB_TOKEN",
          "description": "GitHub 令牌。细粒度令牌给 Actions 读权限即可查看，重跑还要 Actions 写权限，看 Release 要 Contents 读权限。",
          "isRequired": true,
          "isSecret": true
        },
        {
          "name": "GITHUB_REPO",
          "description": "要看的仓库（owner/name），多个用逗号分隔。不填就看你最近推送过的 5 个仓库。"
        }
      ],
      "version": "0.1.1",
      "fileSha256": "3c7e21283ca886e2df8be7875365e0683f028257a0f85d26d0f94fef04e432ee"
    }
  ],
  "_meta": {
    "io.github.opspanel/plugin": {
      "artifacts": {
        "darwin/amd64": {
          "url": "https://github.com/michael-ltm/opspanel-plugins/releases/download/github-actions-v0.1.1/github-actions-darwin-amd64",
          "sha256": "86db7d78c04accacbb2fe35b990dfc25071fd9323ed3d3271cbb2779294ce661"
        },
        "darwin/arm64": {
          "url": "https://github.com/michael-ltm/opspanel-plugins/releases/download/github-actions-v0.1.1/github-actions-darwin-arm64",
          "sha256": "c6c3e7f4c1dc0f0abf71f5d02e6042440320a76ac54110e43bedb7c98e50852c"
        },
        "linux/amd64": {
          "url": "https://github.com/michael-ltm/opspanel-plugins/releases/download/github-actions-v0.1.1/github-actions-linux-amd64",
          "sha256": "3c7e21283ca886e2df8be7875365e0683f028257a0f85d26d0f94fef04e432ee"
        },
        "linux/arm64": {
          "url": "https://github.com/michael-ltm/opspanel-plugins/releases/download/github-actions-v0.1.1/github-actions-linux-arm64",
          "sha256": "ab5f2724e1097b0c29c2a2cc2a6cf77870e08f20cbb1225f448f7097879075ca"
        },
        "windows/amd64": {
          "url": "https://github.com/michael-ltm/opspanel-plugins/releases/download/github-actions-v0.1.1/github-actions-windows-amd64.exe",
          "sha256": "ef12fa8eb76d99e7a706a0754cf32eeefe2da68bfdf3fda73e66be7494db75ad"
        },
        "windows/arm64": {
          "url": "https://github.com/michael-ltm/opspanel-plugins/releases/download/github-actions-v0.1.1/github-actions-windows-arm64.exe",
          "sha256": "80f3eb9b19278871b39a123d791de18b02d582b2804e210b296c3f6a9e69c5e9"
        }
      },
      "i18n": {
        "en": {
          "description": "Watch GitHub Actions from the panel: recent runs, the log around where a failed job broke, and releases; re-run failed jobs. Needs a GitHub token.",
          "runs": "Recent runs",
          "colRepo": "Repository",
          "colWorkflow": "Workflow",
          "colBranch": "Branch",
          "colState": "State",
          "colStarted": "Started",
          "actFailLog": "Failure log",
          "actRerun": "Re-run failed",
          "actOpen": "Open",
          "tool.runs_list.title": "Recent runs",
          "tool.runs_list.description": "The latest workflow runs",
          "tool.run_logs.title": "Failure log",
          "tool.run_logs.description": "Log lines around where a failed job broke",
          "tool.run_rerun.title": "Re-run failed jobs",
          "tool.run_rerun.description": "Run the failed jobs of a run again",
          "tool.releases_list.title": "Releases",
          "tool.releases_list.description": "The repository's latest releases"
        }
      },
      "ui": [
        {
          "id": "runs",
          "type": "table",
          "title": "最近的运行",
          "titleKey": "runs",
          "tool": "runs_list",
          "path": "/runs",
          "refresh": 60,
          "columns": [
            {
              "key": "repo",
              "title": "仓库",
              "titleKey": "colRepo"
            },
            {
              "key": "workflow",
              "title": "工作流",
              "titleKey": "colWorkflow"
            },
            {
              "key": "branch",
              "title": "分支",
              "titleKey": "colBranch"
            },
            {
              "key": "state",
              "title": "状态",
              "titleKey": "colState",
              "format": "badge"
            },
            {
              "key": "createdAt",
              "title": "开始于",
              "titleKey": "colStarted",
              "format": "time"
            }
          ],
          "rowActions": [
            {
              "id": "logs",
              "title": "失败日志",
              "titleKey": "actFailLog",
              "icon": "logs",
              "tool": "run_logs",
              "arguments": {
                "repo": "{repo}",
                "run_id": "{id}"
              },
              "display": "dialog",
              "resultPath": "/failedJobs",
              "when": {
                "key": "state",
                "in": [
                  "failure",
                  "cancelled",
                  "timed_out",
                  "startup_failure"
                ]
              }
            },
            {
              "id": "rerun",
              "title": "重跑失败项",
              "titleKey": "actRerun",
              "icon": "refresh",
              "tool": "run_rerun",
              "arguments": {
                "repo": "{repo}",
                "run_id": "{id}"
              },
              "confirm": true,
              "when": {
                "key": "state",
                "in": [
                  "failure",
                  "cancelled",
                  "timed_out",
                  "startup_failure"
                ]
              }
            },
            {
              "id": "open",
              "title": "打开",
              "titleKey": "actOpen",
              "icon": "external",
              "link": "{url}",
              "unless": {
                "key": "url",
                "in": [
                  ""
                ]
              }
            }
          ]
        }
      ],
      "tools": {
        "runs_list": {
          "title": "最近的运行",
          "description": "各仓库最近的工作流运行"
        },
        "run_logs": {
          "title": "失败日志",
          "description": "只取失败步骤附近的日志"
        },
        "run_rerun": {
          "title": "重跑失败的任务",
          "description": "重新运行一次运行里失败的任务"
        },
        "releases_list": {
          "title": "发布列表",
          "description": "仓库最近的 Release"
        }
      }
    }
  }
}

{
