          "description": "接收消息的 Telegram 会话 ID。"
        },
        {
          "name": "FEISHU_WEBHOOK",
          "description": "飞书群机器人的 Webhook 地址。",
          "isSecret": true
        },
        {
          "name": "FEISHU_SECRET",
          "description": "飞书机器人开启了签名校验时，填写签名密钥。",
          "isSecret": true
        }
      ],
      "version": "0.1.1",
      "fileSha256": "3e64e14c699db3c329f57e2a6509977fbd4c35852026fe0da9bd3469001309bd"
    }
  ],
