        },
        "darwin/arm64": {
          "url": "https://github.com/michael-ltm/opspanel-plugins/releases/download/notify-v0.1.1/notify-darwin-arm64",
          "sha256": "b43472b13cd8842be934de3c9cc58746ceb7da7b3a0c89d45b2ef2c44f18cbfd"
        },
        "linux/amd64": {
          "url": "https://github.com/michael-ltm/opspanel-plugins/releases/download/notify-v0.1.1/notify-linux-amd64",
          "sha256": "3e64e14c699db3c329f57e2a6509977fbd4c35852026fe0da9bd3469001309bd"
        },
        "linux/arm64": {
          "url": "https://github.com/michael-ltm/opspanel-plugins/releases/download/notify-v0.1.1/notify-linux-arm64",
          "sha256": "4122271d3b8518e863a0b474ab4b38ab9d457f45dc91c49bd52ca45511fd314e"
        },
        "windows/amd64": {
          "url": "https://github.com/michael-ltm/opspanel-plugins/releases/download/notify-v0.1.1/notify-windows-amd64.exe",
          "sha256": "7b086b13f4886459f60d9a1a94d8227b93173fb54cfc0f834af8f634ca59b93a"
